fun buildVSHoverRawContent(imageId: VSImageId?, quickInfoRuns: GoSlice<VSClassifiedTextRun?>, documentationRuns: GoSlice<VSClassifiedTextRun?>): VSContainerElement? {
    if (quickInfoRuns.len == 0) {
        return null
    }
    val displayLine: VSContainerElement? = VSContainerElement(style = VSContainerElementStyle(0), elements = GoSlice.of(VSImageElementOrClassifiedTextElementOrContainerElement.ELEM, VSImageElementOrClassifiedTextElementOrContainerElement(imageElement = VSImageElement(imageId = imageId)), VSImageElementOrClassifiedTextElementOrContainerElement(classifiedTextElement = VSClassifiedTextElement(runs = quickInfoRuns))))
    if (documentationRuns.len == 0) {
        return displayLine
    }
    return VSContainerElement(style = VSContainerElementStyle(1), elements = GoSlice.of(VSImageElementOrClassifiedTextElementOrContainerElement.ELEM, VSImageElementOrClassifiedTextElementOrContainerElement(containerElement = displayLine), VSImageElementOrClassifiedTextElementOrContainerElement(classifiedTextElement = VSClassifiedTextElement(runs = documentationRuns))))
}

